local Singleton = import('Frame.Singleton')
---@class BeginnerMgr
---@field GetInstance fun(self:BeginnerMgr):BeginnerMgr
local BeginnerMgr = Class('BeginnerMgr', Singleton)
local BeginnerDojo = import("Game.Dojo.BeginnerDojo")

local settingMgr = SettingMgr:GetInstance()

function BeginnerMgr:__init()
    ---@type BeginnerDojo
    self.beginnerDojo = nil
    self.chooseStep = 1
end

function BeginnerMgr:RequestHomeDojo(callBack)
    GameUtils.Request(Interfaces.ActivityBeginnerHome, nil, function(request, response)
        if checkNumber(response.errCode) == 0 then
            if isNull(self.beginnerDojo) then
                self.beginnerDojo = BeginnerDojo.New()
            end
            self.beginnerDojo:Fill(response.data)
            self:FillSevenSettingData()
            self:FillDailySetting()
            if callBack then
                callBack()
            end
        end
    end)
end

function BeginnerMgr:FillDailySetting()
    ---@type BaseSetting
    local setting = settingMgr:GetSetting(AutoIds.IdSetting8927, "ActivityPtDayTaskVo")
    for i, v in pairs(self.beginnerDojo.dailyTasks) do
        local vo = setting:Get(v.id)
        if isNotNull(vo) then
            v.desc = vo.desc
            v.unlockId = vo.unlockId
            v.taskContentType = vo.taskContentType
            v.taskContentId = vo.taskContentId
            v.taskContentNum = vo.taskContenNum
            v.rewardId = vo.rewardId
            v.rewardNum = vo.rewardNum
            v.openType = vo.openType
            v.openParameter = vo.openParameter
        end
    end
end

function BeginnerMgr:FillSevenSettingData()
    ---@type BaseSetting
    local setting = settingMgr:GetSetting(AutoIds.IdSetting8921, "SevenDaysTaskVo")
    for i, v in pairs(self.beginnerDojo.tasks) do
        local id = checkNumber(v.id)
        ---@type SevenDaysTaskVo
        local vo = setting:Get(id)
        if isNotNull(vo) then
            ---查找到数据
            v.openDay = checkNumber(vo.openDay)
            v.taskContentNum = checkNumber(vo.taskContentNum)
            v.taskVo = vo
        end
    end
end

---GetHomeDojo
---@return BeginnerDojo
function BeginnerMgr:GetHomeDojo()
    return self.beginnerDojo
end

---GetTasksByGroup
---得到每天的任务组
---@param day number
function BeginnerMgr:GetTasksByGroup(day)
    day = checkNumber(day)
    local t = {}
    for i, v in pairs(self.beginnerDojo.tasks) do
        if checkNumber(v.openDay) == day then
            table.insert(t, v)
        end
    end
    return t
end

---GetTaskGroups
---@return table
function BeginnerMgr:GetTaskGroups()
    local t = {}
    for i, v in pairs(self.beginnerDojo.tasks) do
        if checkNumber(v.openDay) > 0 then
            if not table.indexof(t, checkNumber(v.openDay)) then
                table.insert(t, checkNumber(v.openDay))
            end
        end
    end
    table.sort(t)
    return t
end

---GetTaskGroups
---@return table
function BeginnerMgr:GetTaskMaxUnlockGroupId()
    return checkInt(self.beginnerDojo.todayNum)
end

---HasTaskGroupDawned
---@return boolean
function BeginnerMgr:HasTaskGroupDawned(day)
    local hasDrawn = true
    for i, v in pairs(self.beginnerDojo.tasks) do
        if checkNumber(v.openDay) == checkNumber(day) then
            if checkNumber(v.progress) >= checkNumber(v.taskContentNum) and checkNumber(v.hasDrawn) == 0 then
                ---存在未领取的节点
                hasDrawn = false
            end
        end
    end
    return hasDrawn
end

---HasTaskGroupDawned
---@return boolean
function BeginnerMgr:GetTaskGroupProgress(day)
    local pro = 0
    local max = 0
    for i, v in pairs(self.beginnerDojo.tasks) do
        if checkNumber(v.openDay) == checkNumber(day) then
            max = max + 1
            if checkNumber(v.hasDrawn) == 1 then
                pro = pro + 1
            end
        end
    end
    return pro, max
end

function BeginnerMgr:HasRedPointGroupByDay(day)
    local hasRed = false
    for i, v in pairs(self.beginnerDojo.tasks) do
        if checkNumber(v.openDay) == checkNumber(day) then
            if checkNumber(v.progress) >= checkNumber(v.taskContentNum) and checkNumber(v.hasDrawn) == 0 then
                hasRed = true
            end
        end
    end
    return hasRed
end

---@return boolean
function BeginnerMgr:UpdateTaskStatus(day, taskId, hasDrawn)
    for i, v in pairs(self.beginnerDojo.tasks) do
        if checkNumber(v.openDay) == checkNumber(day) and checkNumber(v.id) == checkNumber(taskId) then
            v.hasDrawn = checkNumber(hasDrawn)
        end
    end
end

function BeginnerMgr:IsTaskCompleted()
    local count = table.count(self.beginnerDojo.tasks)
    local progress = 0
    for i, v in pairs(self.beginnerDojo.tasks) do
        if checkNumber(v.hasDrawn) == 1 then
            progress = progress + 1
        end
    end
    return progress == count
end

---GetTaskInfo
---return table
function BeginnerMgr:GetTasks()
    return self.beginnerDojo.tasks
end

----redPoint----------------------
function BeginnerMgr:CheckTaskRedPoint()
    local count = 0
    for k, v in pairs(self.beginnerDojo.tasks) do
        --一到七天
        if k <= checkNumber(self.beginnerDojo.todayNum) then
            --每天的所有任务
            if checkNumber(v.progress) >= checkNumber(v.taskContentNum) then
                if checkNumber(v.hasDrawn) == 0 then
                    count = count + 1
                end
            end
        else
            break
        end
    end

    local isCompleted = self:IsTaskCompleted() --完成所有任务
    local isFinalPrizeDrawn = checkNumber(self.beginnerDojo.drawnFinalPrize) == 1
    if isCompleted and not isFinalPrizeDrawn then
        count = count + 1
    end
    return count > 0
end

function BeginnerMgr:CheckBossRedPoint()
    local isCanOneKeyDraw = self:IsCanOneKeyDrawReward()
    return isCanOneKeyDraw
end

function BeginnerMgr:CheckWelfareRedPoint()
    local hasRedPoint = false
    for i, v in pairs(self.beginnerDojo.dailyTasks) do
        if checkNumber(v.progress) >= checkNumber(v.taskContentNum) and checkNumber(v.hasDrawn) == 0 then
            hasRedPoint = true
            break
        end
    end
    return hasRedPoint
end

function BeginnerMgr:CheckJumpRedPoint()
    return false
end

function BeginnerMgr:CheckAchievementRedPoint()
    local data = self.beginnerDojo.achievements
    for j, v in pairs(data) do
        local taskVo = CfUtils.GetCfVo(AutoIds.IdSetting8936,"BeginnerAchievementTaskVo", v.id)
        local isCanDraw = (v.progress >= taskVo.taskContenNum)  and (v.hasDrawn ~= 1)
        if isCanDraw then
            return true
        end
    end
    return false
end

function BeginnerMgr:CheckGiftRedPoint()
    local data = self.beginnerDojo:GetGiftInfo()
    for j, v in pairs(data) do
        local isFree = self:ProductIsFree(v)
        if isFree and v.currentStock > 0 then
            return true
        end
    end
    return false
end

function BeginnerMgr:ProductIsFree(product)
    if product.prices and table.count(product.prices) > 0 then
        for i = 1, #product.prices do
            if product.prices[i].current ~= 0 then
                return false
            end
        end
        return true
    end

    return checkInt(product.isFree) == 1
end

---更新主界面红点
---UpdateRegressHomeRedPoint
function BeginnerMgr:UpdateRegressHomeRedPoint()
    local taskRedPoint = self:CheckTaskRedPoint()
    if taskRedPoint then
        GameUtils.SetRedPointNum(Constants.RedPointConst.MainNewBeginner, 1)
        return
    end
    local bossRedPoint = self:CheckBossRedPoint()
    if bossRedPoint then
        GameUtils.SetRedPointNum(Constants.RedPointConst.MainNewBeginner, 1)
        return
    end
    local welfareRedPoint = self:CheckWelfareRedPoint()
    if welfareRedPoint then
        GameUtils.SetRedPointNum(Constants.RedPointConst.MainNewBeginner, 1)
        return
    end
    local giftRedPoint = self:CheckGiftRedPoint()
    if giftRedPoint then
        GameUtils.SetRedPointNum(Constants.RedPointConst.MainNewBeginner, 1)
        return
    end

    local jumpRedPoint = self:CheckJumpRedPoint()
    if jumpRedPoint then
        GameUtils.SetRedPointNum(Constants.RedPointConst.MainNewBeginner, 1)
        return
    end
    GameUtils.SetRedPointNum(Constants.RedPointConst.MainNewBeginner, 0)
end

