function BeginnerMgr:IsCanOneKeyDrawReward()
    -- 获取所有奖励
    local allRewards = self:GetBossHurtRewards()
    -- 获取所有可领取的奖励
    local historyMaxHurt = self:GetBossHurt()
    local allCanDrawButNotInListRewards = {}
    for _, reward in ipairs(allRewards) do
        ---@type MidFestivalBossDamageRewardVo
        local rewardVo = reward
        if historyMaxHurt >= checkNumber(rewardVo.upperLimit) and (not self:IsHaveDrawBossHurtReward(rewardVo.id)) then
            table.insert(allCanDrawButNotInListRewards, rewardVo)
        end
    end
    return table.count(allCanDrawButNotInListRewards) > 0
end

function BeginnerMgr:DrawHurtReward(id,callBack)
    GameUtils.Request(Interfaces.ActivityBeginnerDrawBossHurtReward, { rewardId = id } , function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local rewards = jsonData.rewards
        self.beginnerDojo:UpdateDrawState(id)
        
        if #rewards > 0 then
            GoodsUtils.DrawRewards(rewards)
            CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        end
        Events.Broadcast(Constants.EventNames.REFRESH_NEW_BEGINNER_RED_POINT)
        if callBack then
            callBack()
        end
    end)
end

function BeginnerMgr:IsHaveDrawBossHurtReward(id)
    return self.beginnerDojo:IsHaveDrawBossHurtReward(id)
end

function BeginnerMgr:GetBossHurt()
    return self.beginnerDojo:GetBossHurt()
end

---开启购买页面
---@param itemData    table 物品数据
---@param storeType OverseaStoreConstants.StoreType
function BeginnerMgr:OpenBuyItemDialog(itemData, storeType ,isCloseSDKSecondConfirm,callBack)
    local OverseaStoreUtils = import('Game.OverseaStore.OverseaStoreUtils')
    local isLocked = OverseaStoreUtils.ProductIsLocked(itemData)
    if isLocked then
        GameUtils.Toast(localize("商品未解锁"))
        return
    end
    
    if checkInt(itemData.isFree) == 1 then
        if OverseaStoreUtils.ProductIsSoldOut(itemData) then
            GameUtils.Toast(localize("商品已售罄"))
        else
            -- 免费商品直接请求
            self:FreeBuyRequest(itemData, callBack)
        end
        return
    end
    
    local goodsVo = nil
    local goodsType = GoodsUtils.GetIdType(itemData.icon)
    if goodsType == Constants.IDType.GoodsGift then
        goodsVo = itemData
    end
    
    local payPoint = isNotNull(itemData.price) and itemData.price or itemData.payPoint
    CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
        goodsId        = itemData.icon,
        goodsNum       = itemData.num,
        prices         = itemData.prices,
        coinPrices     = itemData.coinPrices,
        maxBuyNum      = itemData.currentStock,
        rewards        = itemData.rewards,
        remainTime     = itemData.refreshTime,
        endTime        = itemData.endTime,
        refreshType    = itemData.refreshType,
        goodsVo        = goodsVo,
        payPoint       =  payPoint,
        isCloseSDKSecondConfirm = isCloseSDKSecondConfirm,
        buyCb          = function (price, buyNum)
            if isNotNull(payPoint) then
                self:SDKBuyRequest(itemData)
            else
                self:BuyRequest(itemData.productId, buyNum, price, callBack)
            end
        end
    }})
end

---购买请求
---@param productId   integer  商品id
---@param buyNum      integer  购买数量
---@param price       table    currency:货币id, current:单价（Coin类型为消耗的道具列表）
---@param callback    function 结束回调
function BeginnerMgr:BuyRequest(productId, buyNum, price, callback)
    local requestPath = Interfaces.GroceryCommonBuy
    local data = {
        productId = productId,
        num       = buyNum,
        currency  = price.currency
    }
    
    GameUtils.Request(requestPath, data,
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local responseData = checkTable(response.data)
                    if #responseData.rewards > 0 then
                        local consume = {}
                        
                        table.insert(consume, { ["num"] = -price.current * buyNum;
                                                ["goodsId"] = price.currency, ['productId'] = productId })
                        
                        GoodsUtils.DrawRewards(consume)
                        GoodsUtils.DrawRewards(responseData.rewards)
                        local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
                        CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_buy)
                        
                        if next(checkTable(responseData.nextChest)) ~= nil then
                            --StoreUtils.RefreshNextChest(storeType, productId, responseData.nextChest)
                        else
                            self:RefreshStock(checkInt(productId), checkInt(buyNum))
                        end
                        
                        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                        if callback ~= nil then
                            callback()
                        end
                    end
                end
            end, function(errStr)
                if string.isEmpty(errStr) or errStr == nil then
                    return
                end
                printError("store buy" .. errStr)
            end
    )
end

---免费礼包请求
---@param itemData    table 物品数据
function BeginnerMgr:FreeBuyRequest(itemData,callBack)
    local data = {
        productId    = itemData.productId,
        activityUuid = itemData.activityUuid,
    }
    GameUtils.Request(Interfaces.OverseaStoreFreeDraw, data,
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local responseData = checkTable(response.data)
                    if #responseData.rewards > 0 then
                        GoodsUtils.DrawRewards(responseData.rewards)
                        local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
                        CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_buy)
                        self:RefreshStock(checkInt(itemData.productId), 1)
                        
                        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards, cb = function()
                            if callBack then
                                callBack()
                            end
                        end } })
                        Events.Broadcast(Constants.EventNames.OVERSEA_STORE_RED_POINT_REFRESH)
                    end
                end
            end, function(errStr)
                if string.isEmpty(errStr) or errStr == nil then
                    return
                end
                printError("store free chest buy" .. errStr)
            end
    )
end

function BeginnerMgr:RefreshStock(productId, buyNum)
    local products = self.beginnerDojo:GetGiftInfo()
    for i, v in pairs(products) do
        if v.stock ~= -1 then
            if checkInt(v.productId) == productId then
                v.currentStock = v.currentStock - buyNum
                break
            end
        end
    end
end

